{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve an error or failure reported during an earlier execution step, such as installing a missing build dependency or correcting incompatible code.",
      "source_description": "An earlier observed execution error or failure output that blocks progress.",
      "target_description": "A subsequent agent action intended to resolve that failure."
    },
    {
      "name": "VERIFIES_PRIOR_REPAIR",
      "definition": "A subsequent agent action re-checks or validates whether an earlier repair, modification, or install produced the intended outcome, for example re-running a search to confirm no problematic patterns remain or executing an end-to-end usage snippet after installation.",
      "source_description": "An earlier repair or modification action (or its affected artifact) whose effect is in question.",
      "target_description": "A subsequent verification action that checks the result of the earlier repair."
    },
    {
      "name": "USES_DIAGNOSTIC_FINDING_TO_GUIDE_REPAIR",
      "definition": "The agent uses the output of an earlier diagnostic search or inspection to select and perform a corrective action addressing the issues it identified.",
      "source_description": "A diagnostic observation, such as search or inspection output that identifies problematic code patterns or incompatibilities.",
      "target_description": "The subsequent corrective action selected and executed based on that diagnostic finding."
    }
  ]
}

